deadlock.pseudocode:
def has_deadlock(wait_for):
    # wait_for[p] = p가 기다리는 프로세스 목록
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {p: WHITE for p in wait_for}

    def dfs(p):
        color[p] = GRAY  # 현재 탐색 경로 위
        for q in wait_for[p]:
            if color[q] == GRAY:
                return True  # 사이클 = 교착상태
            if color[q] == WHITE and dfs(q):
                return True
        color[p] = BLACK  # 사이클 없음 확인
        return False

    return any(color[p] == WHITE and dfs(p)
               for p in wait_for)

decision-tree.pseudocode:
def build_tree(rows, features, depth=0):
    labels = [r.label for r in rows]
    if is_pure(labels) or not features or depth >= MAXD:
        return Leaf(majority(labels))  # 정지(사전 가지치기)
    best = max(features, key=lambda f: info_gain(rows, f))
    node = Node(best)
    rest = [f for f in features if f != best]
    for v, subset in split(rows, best).items():
        node.kids[v] = build_tree(subset, rest, depth + 1)
    return node

def info_gain(rows, f):  # 부모 엔트로피 - 가중 자식 엔트로피
    gain = entropy(rows)
    for subset in split(rows, f).values():
        gain -= len(subset) / len(rows) * entropy(subset)
    return gain

def entropy(rows):
    n = len(rows)
    return -sum(c / n * log2(c / n) for c in counts(rows))

