decorator-pattern.pseudocode:
class Coffee:  # ConcreteComponent
    def cost(self):
        return 3000

class CoffeeDecorator:  # Decorator: 같은 인터페이스
    def __init__(self, inner):
        self.inner = inner  # 감싸는 대상(합성)
    def cost(self):
        return self.inner.cost()

class Milk(CoffeeDecorator):
    def cost(self):
        return self.inner.cost() + 500  # 책임 추가

class Shot(CoffeeDecorator):
    def cost(self):
        return self.inner.cost() + 700

drink = Shot(Milk(Coffee()))  # 런타임 중첩
print(drink.cost())  # 4200

deferred-update.pseudocode:
def write(tid, item, value, log, buf):
    log.append(('write', tid, item, value))  # 새 값만 로그에
    buf.setdefault(tid, {})[item] = value  # DB엔 미반영

def commit(tid, log, buf, db):
    log.append(('commit', tid, None, None))
    for item, value in buf.pop(tid, {}).items():
        db[item] = value  # 커밋 이후에만 DB 반영

def recover(log, db):
    # 지연 갱신 회복: NO-UNDO / REDO
    done = {t for kind, t, _, _ in log if kind == 'commit'}
    for kind, tid, item, value in log:  # 로그 순서대로
        if kind == 'write' and tid in done:
            db[item] = value  # REDO (여러 번 해도 결과 동일)
    # 미완료 트랜잭션은 DB에 반영된 적이 없어 무시

deficit-round-robin.pseudocode:
def drr(queues, quantum):
    # queues[i]: 패킷 크기(바이트) 리스트
    deficit = [0] * len(queues)
    while any(queues):
        for i, q in enumerate(queues):
            if not q:
                continue
            deficit[i] += quantum[i]  # 라운드 할당량
            while q and q[0] <= deficit[i]:
                size = q.pop(0)
                deficit[i] -= size
                send(i, size)
            if not q:
                deficit[i] = 0  # 빈 큐는 이월 없음

dependency-preservation.pseudocode:
def closure(X, F):
    # 속성 집합 X의 폐포 X+
    res = set(X)
    while True:
        add = {a for l, r in F if l <= res for a in r}
        if add <= res:
            return res
        res |= add

def preserves(decomp, F):
    for X, Y in F:  # 각 함수 종속 X → Y 검사
        Z = set(X)
        while True:
            # 각 Ri 안에서만 폐포를 구해 Z를 확장
            T = set(Z)
            for Ri in decomp:
                T |= closure(Z & Ri, F) & Ri
            if T == Z:
                break
            Z = T
        if not Y <= Z:
            return False  # 조인 없이는 X → Y 검사 불가
    return True

des.pseudocode:
def feistel_encrypt(block64, subkeys, F):
    L, R = block64 >> 32, block64 & 0xFFFFFFFF  # 32비트씩
    for k in subkeys:  # DES: 16라운드, 48비트 서브키
        L, R = R, L ^ F(R, k)  # F: 확장·S-박스·순열
    return (R << 32) | L  # 마지막 라운드 후 좌우 교환

def feistel_decrypt(block64, subkeys, F):
    # 같은 구조에 서브키만 역순 → F의 역함수 불필요
    return feistel_encrypt(block64, subkeys[::-1], F)

