design-of-experiments.pseudocode:
def full_factorial(k):  # 2^k 설계, 각 인자 -1/+1
    runs = [[]]
    for _ in range(k):
        runs = [r + [lv] for r in runs for lv in (-1, 1)]
    return runs

def contrast(runs, y, signs):
    # (+ 부호 평균) − (− 부호 평균)
    hi = [y[i] for i in range(len(y)) if signs[i] == 1]
    lo = [y[i] for i in range(len(y)) if signs[i] == -1]
    return sum(hi) / len(hi) - sum(lo) / len(lo)

def main_effect(runs, y, j):  # 인자 j의 주효과
    return contrast(runs, y, [r[j] for r in runs])

def interaction(runs, y, j, k):  # 인자 j×k 교호작용
    return contrast(runs, y, [r[j] * r[k] for r in runs])
